package br.jus.tjro.gabinete.infrastructure.json;

import br.jus.tjro.gabinete.fonte.dados.core.FonteDadosEnum;
import br.jus.tjro.gabinete.model.gab.enums.SistemaOrigemEnum;
import br.jus.tjro.gabinete.model.gab.minuta.MinutaRecebida;
import br.jus.tjro.gabinete.model.gab.minuta.MinutaRecebidaStatus;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;


public class MinutaRecebidaJsonTests {


    private final String json = "{\n" +
        "\"sistema\": \"PJEPG\",\n" +
        "\"idProcessoSistemaLegado\": 666,\n" +
        "\"idMovimentoProcessual\": 6661,\n" +
        "\"html\": \"<b>windson<b>\"\n" +
        "}";


    private final String jsonCompleto = "{\n" +
        "\"sistema\": \"PJEPG\",\n" +
        "\"idProcessoSistemaLegado\": 666,\n" +
        "\"idMovimentoProcessual\": 6661,\n" +
        "\"html\": \"<b>windson<b>\",\n" +
        "\"sistemaOrigem\": \"cartorio\",\n" +
        "\"referenciaOrigem\": \"hashMongoCartorio\",\n" +
        "\"nomeAutor\": \"Autor windson\"\n," +
        "\"naoSei\": \"NinguemLiga\"\n" +
    "}";

    private final String jsonKafka = "{\n" +
        "  \"html\": \"\\u003cfigure class\\u003d\\\"image\\\"\\u003e\\u003cimg src\\u003d\\\"data:image/png;base64,\\\" alt\\u003d\\\"Timbre\\\"\\u003e\\u003c/figure\\u003e\\u003cp style\\u003d\\\"margin-left:0;\\\"\\u003eTRIBUNAL DE JUSTIÇA DO ESTADO DE RONDÔNIA\\u003c/p\\u003e\\u003cp style\\u003d\\\"margin-left:0;\\\"\\u003e\\u0026nbsp;\\u003c/p\\u003e\\u003cp style\\u003d\\\"margin-left:0;\\\"\\u003eTeste de envio de minuta de expediente para validação no gabinete\\u003c/p\\u003e\\u003cp style\\u003d\\\"margin-left:0;\\\"\\u003e\\u0026nbsp;\\u003c/p\\u003e\\u003cp style\\u003d\\\"margin-left:0;\\\"\\u003eRua José Camacho, 585 - Bairro Olaria - CEP 76801-330 - Porto Velho - RO - www.tjro.jus.br\\u003cbr\\u003eTelefone: (69) 3217-1100/1348 - e-mail: suportesei@tjro.jus.br\\u003c/p\\u003e\",\n" +
        "  \"idProcessoSistemaLegado\": \"1021432\",\n" +
        "  \"sistema\": \"PJEPG\",\n" +
        "  \"sistemaOrigem\": \"cartorio\",\n" +
        "  \"referenciaOrigem\": \"1682985963\",\n" +
        "  \"nomeAutor\": \"01847004261\",\n" +
        "  \"idMovimentoProcessual\": 11020\n" +
        "}";

    @Test
    public void parse() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        MinutaRecebida resultado = mapper.reader().forType(MinutaRecebida.class).readValue(json);
        assertEquals("<b>windson<b>",resultado.getHtml());
        assertEquals("Não Informado",resultado.getNomeAutor());
        assertEquals(null,resultado.getReferenciaOrigem());
        assertEquals(FonteDadosEnum.PJEPG,resultado.getSistema());
        assertEquals(null,resultado.getSistemaOrigem());
        assertEquals(null,resultado.getId());
        assertEquals(6661l,resultado.getIdMovimentoProcessual());
        assertEquals(MinutaRecebidaStatus.PENDENTE,resultado.getStatus());
    }

    @Test
    public void parseCompleto() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        MinutaRecebida resultado = mapper.reader().forType(MinutaRecebida.class).readValue(jsonCompleto);
        assertEquals("<b>windson<b>",resultado.getHtml());
        assertEquals("Autor windson",resultado.getNomeAutor());
        assertEquals("hashMongoCartorio",resultado.getReferenciaOrigem());
        assertEquals(FonteDadosEnum.PJEPG,resultado.getSistema());
        assertEquals(SistemaOrigemEnum.cartorio,resultado.getSistemaOrigem());
        assertEquals(null,resultado.getId());
        assertEquals(6661l,resultado.getIdMovimentoProcessual());
        assertEquals(MinutaRecebidaStatus.PENDENTE,resultado.getStatus());
    }

    @Test
    public void pareJsonKafka() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        MinutaRecebida resultado = mapper.reader().forType(MinutaRecebida.class).readValue(jsonKafka);
        assertNotNull(resultado.getHtml());
        assertEquals("01847004261",resultado.getNomeAutor());
        assertEquals("1682985963",resultado.getReferenciaOrigem());
        assertEquals(FonteDadosEnum.PJEPG,resultado.getSistema());
        assertEquals(SistemaOrigemEnum.cartorio,resultado.getSistemaOrigem());
        assertEquals(null,resultado.getId());
        assertEquals(MinutaRecebidaStatus.PENDENTE,resultado.getStatus());
    }

}
